  world.stations.pots[0].state = 'cooking';
  world.stations.pots[0].progress = 0.6;
  world.stations.plate.items = ['bread', 'beef_cooked', 'lettuce_chopped'];
  world.chef.x = 1060;
  world.chef.y = 340;
  world.chef.carry = 'tomato_chopped';
  world.chef.facing = -1;
